(function (global, factory) {
    typeof exports === 'object' && typeof module !== 'undefined' ? module.exports = factory() :
    typeof define === 'function' && define.amd ? define(factory) :
    (global = global || self, global.FallCake = factory());
}(this, (function () {
    'use strict';

    /**
     * FallCake - 下落蛋糕效果库
     * @param {string} containerId - 容器元素ID
     * @param {Object} options - 配置选项
     * @param {number} [options.particleCount=18] - 漂浮粒子数量
     * @param {number} [options.particleInterval=850] - 粒子生成间隔(ms)
     * @param {number} [options.particleLifespan=22000] - 粒子存活时间(ms)
     */
    class FallCake {
        constructor(containerId, options = {}) {
            this.container = typeof containerId === 'string'
                ? document.getElementById(containerId)
                : containerId;
            
            if (!this.container) {
                console.error(`FallCake: Container not found: ${containerId}`);
                return;
            }

            this.config = Object.assign({
                particleCount: 18,
                particleInterval: 850,
                particleLifespan: 22000
            }, options);

            this.injectStyles();
            this.createParticleLayer();
            this.startParticles();
        }

        injectStyles() {
            if (document.getElementById('fall-cake-styles')) return;

            const style = document.createElement('style');
            style.id = 'fall-cake-styles';
            style.textContent = `
                .fall-cake-particle-layer {
                    position: fixed;
                    top: 0;
                    left: 0;
                    width: 100%;
                    height: 100%;
                    pointer-events: none;
                    z-index: 9999;
                    overflow: hidden;
                }
                .fall-cake-float-box {
                    position: absolute;
                    border-radius: 4px;
                    animation: fallCakeFloat linear forwards;
                }
                @keyframes fallCakeFloat {
                    0% {
                        transform: translateY(-150px) rotate(0deg);
                        opacity: 0;
                    }
                    10% {
                        opacity: 1;
                    }
                    90% {
                        opacity: 1;
                    }
                    100% {
                        transform: translateY(100vh) rotate(360deg);
                        opacity: 0;
                    }
                }
            `;
            document.head.appendChild(style);
        }

        createParticleLayer() {
            this.particleLayer = document.createElement('div');
            this.particleLayer.className = 'fall-cake-particle-layer';
            this.container.appendChild(this.particleLayer);
        }

        createBox() {
            const box = document.createElement('div');
            box.className = 'fall-cake-float-box';

            const size = Math.random() * 90 + 24;
            box.style.width = `${size}px`;
            box.style.height = `${size}px`;
            box.style.left = `${Math.random() * 100}vw`;
            box.style.animationDuration = `${Math.random() * 12 + 8}s`;
            box.style.transform = `rotate(${Math.random() * 360}deg)`;
            box.style.background = `rgba(255, 255, 255, ${Math.random() * 0.18 + 0.08})`;

            this.particleLayer.appendChild(box);
            setTimeout(() => {
                if (box.parentNode) {
                    box.remove();
                }
            }, this.config.particleLifespan);
        }

        startParticles() {
            // 初始粒子
            for (let i = 0; i < this.config.particleCount; i++) {
                this.createBox();
                const box = this.particleLayer.lastElementChild;
                if (box) {
                    box.style.animationDelay = `-${Math.random() * 20}s`;
                }
            }

            // 定时生成新粒子
            this.intervalId = setInterval(() => {
                this.createBox();
            }, this.config.particleInterval);
        }

        /**
         * 停止粒子生成
         */
        stop() {
            if (this.intervalId) {
                clearInterval(this.intervalId);
                this.intervalId = null;
            }
        }

        /**
         * 重新开始粒子生成
         */
        restart() {
            this.stop();
            this.startParticles();
        }

        /**
         * 销毁实例，释放资源
         */
        destroy() {
            this.stop();
            if (this.particleLayer) {
                this.particleLayer.innerHTML = '';
                if (this.particleLayer.parentNode) {
                    this.particleLayer.parentNode.removeChild(this.particleLayer);
                }
            }
        }
    }

    return FallCake;
})));
